import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios';
import './Auth.css';

const Login = ({ onLogin }) => {
  const [formData, setFormData] = useState({
    email: '',
    password: ''
  });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  // For testing - remove this in production
  const API_BASE_URL = process.env.REACT_APP_API_BASE_URL || 'http://localhost:5000';

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
    setError('');
  };

  // Mock login for testing without backend
  const mockLogin = () => {
    console.log('Mock login with:', formData);
    setTimeout(() => {
      onLogin('mock-token-123', {
        id: 1,
        name: 'Test User',
        email: formData.email
      });
    }, 1000);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    // Use mock login for testing (remove when backend is ready)
    if (!API_BASE_URL.includes('localhost:5000')) {
      return mockLogin();
    }

    try {
      console.log('Sending login request to:', `${API_BASE_URL}/api/auth/login`);

      const response = await axios.post(`${API_BASE_URL}/api/auth/login`, formData, {
        timeout: 5000,
        headers: {
          'Content-Type': 'application/json'
        }
      });

      console.log('Login response:', response.data);

      if (response.data.success) {
        onLogin(response.data.token, response.data.user);
      } else {
        setError(response.data.message || 'Login failed');
      }
    } catch (error) {
      console.error('Login error:', error);

      // If backend is not available, use mock login
      if (error.code === 'NETWORK_ERROR' || error.code === 'ECONNREFUSED') {
        console.log('Backend not available, using mock login');
        mockLogin();
      } else {
        setError(error.response?.data?.message || 'Login failed. Please try again.');
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="auth-container">
      <div className="auth-card">
        <div className="logo">
          <i className="fas fa-film"></i>
          Movie Ticket App
        </div>
        <p className="subtitle">Sign in to your account</p>

        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label htmlFor="email">Email</label>
            <input
              type="email"
              id="email"
              name="email"
              value={formData.email}
              onChange={handleChange}
              required
              placeholder="Enter your email"
            />
          </div>

          <div className="form-group">
            <label htmlFor="password">Password</label>
            <input
              type="password"
              id="password"
              name="password"
              value={formData.password}
              onChange={handleChange}
              required
              placeholder="Enter your password"
            />
          </div>

          {error && <div className="error-message">{error}</div>}

          <button 
            type="submit" 
            className="btn"
            disabled={loading}
          >
            {loading ? 'Signing In...' : 'Sign In'}
          </button>
        </form>

        <p className="auth-switch">
          Don't have an account? 
          <Link to="/register" className="switch-link">Sign up</Link>
        </p>

        {/* Test credentials hint */}
        <div className="test-hint">
          <p>For testing, use any email and password</p>
        </div>
      </div>
    </div>
  );
};

export default Login;
